from typing import Dict, Union, Any
import os
import sys

# Add parent directory to path for imports when run as standalone script
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from utils.validation_parser import (
    check_tool_called,
    is_validation_successful,
)


def validate_component_blocks(
    output: str, context: Dict[str, Any]
) -> Dict[str, Union[bool, float, str]]:
    tool_name = "validate_component_codeblocks"

    # Check if the tool was called
    if not check_tool_called(output, tool_name):
        return {
            "pass": False,
            "score": 0.0,
            "reason": f"{tool_name} tool was not called.",
        }

    # Check if validation was successful
    if is_validation_successful(output, tool_name):
        return {
            "pass": True,
            "score": 1.0,
            "reason": f"{tool_name} validation successful.",
        }

    # Validation was called but failed
    return {
        "pass": False,
        "score": 0.0,
        "reason": f"{tool_name} validation failed.",
    }


def get_assert(output: str, context: Dict[str, Any]) -> Dict[str, Any]:
    return validate_component_blocks(output, context)
